('lib/content/pa_scolarite/cadres_juridiques_pages/enquete_preliminaire/enquete_preliminaire_chapitre2_procedure_page.dart','f00044','2.2.1.1 — Dispositions générales',44,'_Paragraph','Les officiers de police judiciaire peuvent mettre en œuvre tous les actes de l’enquête préliminaire. En revanche, les agents de police judiciaire ont une ','Les officiers de police judiciaire peuvent mettre en œuvre tous les actes de l’enquête préliminaire. En revanche, les agents de police judiciaire ont une ','{}'::jsonb,true),
