('lib/content/pa_scolarite/cadres_juridiques_pages/enquete_preliminaire/enquete_preliminaire_chapitre2_procedure_page.dart','f00144','2.3.7.1 — L’audition du témoin',144,'_Paragraph','juge des libertés et de la détention (art. 76 C.P.P.) peut être nécessaire, sous conditions.','juge des libertés et de la détention (art. 76 C.P.P.) peut être nécessaire, sous conditions.','{}'::jsonb,true),
('lib/content/pa_scolarite/cadres_juridiques_pages/enquete_preliminaire/enquete_preliminaire_chapitre2_procedure_page.dart','f00145','2.3.7.1 — L’audition du témoin',145,'_Paragraph','Les témoins ne pouvant être soupçonnés ne peuvent être retenus que le temps strictement nécessaire à leur audition, dans la limite de quatre heures. Ils peuvent refuser de déposer, ','Les témoins ne pouvant être soupçonnés ne peuvent être retenus que le temps strictement nécessaire à leur audition, dans la limite de quatre heures. Ils peuvent refuser de déposer, ','{}'::jsonb,true),
