('lib/content/pa_scolarite/cadres_juridiques_pages/enquete_preliminaire/enquete_preliminaire_fouilles_page.dart','f00041','2.3.6.2 – La fouille de véhicule',41,'TextSpan','Cependant, la fouille d’un véhicule, par l’intrusion dans l’intimité de la vie privée qu’elle permet, est assimilable à une perquisition. ','Cependant, la fouille d’un véhicule, par l’intrusion dans l’intimité de la vie privée qu’elle permet, est assimilable à une perquisition. ','{}'::jsonb,true),
